class Solution {
    private int limit;
    public TreeNode sufficientSubset(TreeNode root,int limit){
        this.limit=limit;
        return prune(root,0);
    }
    private TreeNode prune(TreeNode node,int sum){
        if(node==null)return null;
        int current=sum+node.val;
        if(node.left==null&&node.right==null)return current>=limit?node:null;
        node.left=prune(node.left,current);
        node.right=prune(node.right,current);
        return node.left==null&&node.right==null?null:node;
    }
}

