class Solution {
    int limit;
    TreeNode* prune(TreeNode* node,int sum){
        if(!node)return nullptr;
        int current=sum+node->val;
        if(!node->left&&!node->right)return current>=limit?node:nullptr;
        node->left=prune(node->left,current);
        node->right=prune(node->right,current);
        return !node->left&&!node->right?nullptr:node;
    }
    public:TreeNode* sufficientSubset(TreeNode* root,int inputLimit){
        limit=inputLimit;
        return prune(root,0);
    }
};
